// Filter for rows needing AI generation (Topic is non-empty AND Status is empty or 'Pending')
// Process strictly 1 row per run to stay well within Render Free 512MB RAM & OpenRouter rate limits.
const allItems = $input.all();
const eligible = [];

for (const item of allItems) {
  const row = item.json;
  const topic = String(row['Topic'] || '').trim();
  const status = String(row['Status'] || '').trim().toLowerCase();
  const linkedInDraft = String(row['LinkedIn_Post'] || '').trim();

  if (topic.length > 0 && (status === '' || status === 'pending') && linkedInDraft === '') {
    const rawImageFlag = String(row['Include Image?'] || 'No').trim().toLowerCase();
    const includeImageNormalized = (rawImageFlag === 'yes' || rawImageFlag === 'true') ? 'Yes' : 'No';
    const mentionsNormalized = String(row['Mentions (Optional)'] || '').trim();

    eligible.push({
      json: {
        row_number: row.row_number,
        Topic: topic,
        'Include Image?': includeImageNormalized,
        'Mentions (Optional)': mentionsNormalized,
        Status: 'Processing'
      }
    });
    break; // Strictly 1 row per execution cycle for maximum crash-resilience
  }
}

return eligible;

// ============================================================================
// ZERO-TOUCH META-PROMPTING ENGINE (OPENROUTER DYNAMIC FREE-TIER ROUTING)
// Strictly implements Section 3 of Final Automation Architecture PDF
// ============================================================================
const inputRow = $('03_Filter_And_Sanitize_Input').first().json;
const topic = inputRow['Topic'];
const includeImage = inputRow['Include Image?'];
const mentions = inputRow['Mentions (Optional)'] || '';

const apiKey = $env.OPENROUTER_API_KEY;
const baseUrl = ($env.OPENROUTER_BASE_URL || 'https://openrouter.ai/api/v1').replace(/\/$/, '');
const configuredModel =$env.OPENROUTER_MODEL || 'qwen/qwen-2.5-72b-instruct:free';

if (!apiKey) {
  throw new Error('OPENROUTER_API_KEY is missing from environment variables.');
}

const systemPrompt = [
  "You are an expert social media strategist. Determine the best tone per platform.",
  "If handles are provided in the 'Mentions' variable, weave them naturally into the platform-specific post text. If empty, rely only on hashtags.",
  "CRITICAL RULES:",
  "1. If 'Image Needed' is 'No' (case-insensitive), you MUST set both \"image_gen_prompt\" and \"image_description\" to null.",
  "2. If 'Image Needed' is 'Yes' (case-insensitive), \"image_gen_prompt\" MUST be a highly detailed, photorealistic 4k prompt for FLUX.1, and \"image_description\" MUST be concise accessibility alt-text describing the image.",
  "3. Return ONLY a raw, valid JSON object with NO markdown formatting, NO ```json code blocks, and NO extra text:",
  '{ "linkedin_post": "Professional tone text, handles, hashtags", "facebook_post": "Conversational text, handles, hashtags", "instagram_post": "Visual tone, emoji-heavy, hashtags", "image_gen_prompt": "A highly detailed 4k prompt for FLUX.1 (or null)", "image_description": "Alt-text describing the image (or null)" }'
].join('\n');

const userPrompt = `Topic: ${topic} | Image Needed: ${includeImage} | Mentions: ${mentions}`;

function extractCleanJson(rawText) {
  let cleaned = String(rawText || '').trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  return JSON.parse(cleaned);
}

// Step 1: Dynamically discover live 0-cost free models on OpenRouter
let candidateModels = [configuredModel];
try {
  const modelsResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/models`,
    headers: { 'Authorization': `Bearer ${apiKey}` },
    json: true,
    timeout: 15000
  });
  const dataList = (modelsResp && modelsResp.data) ? modelsResp.data : [];
  for (const m of dataList) {
    const p = String(m?.pricing?.prompt ?? '1');
    const c = String(m?.pricing?.completion ?? '1');
    if ((p === '0' || p === '0.0') && (c === '0' || c === '0.0')) {
      if (m.id && !m.id.includes('embed') && !m.id.includes('clip') && !candidateModels.includes(m.id)) {
        candidateModels.push(m.id);
      }
    }
  }
} catch (e) {
  // Fallback static list if /models discovery times out
  const fallbacks = [
    'nvidia/nemotron-3.5-super-vl:free',
    'qwen/qwen-2.5-72b-instruct:free',
    'google/gemma-3-27b-it:free',
    'meta-llama/llama-3.3-70b-instruct:free'
  ];
  for (const fb of fallbacks) {
    if (!candidateModels.includes(fb)) candidateModels.push(fb);
  }
}

let parsedOutput = null;
let usedModel = null;
let lastError = '';

for (const modelId of candidateModels.slice(0, 12)) {
  try {
    const chatResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/chat/completions`,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': $env.WEBHOOK_URL || '[https://zero-touch-n8n.onrender.com](https://zero-touch-n8n.onrender.com)',
        'X-Title': 'Zero-Touch Social Automation'
      },
      body: {
        model: modelId,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        temperature: 0.4
      },
      json: true,
      timeout: 45000
    });

    const content = chatResp?.choices?.[0]?.message?.content;
    if (!content) throw new Error('Empty response content');
    const candidateJson = extractCleanJson(content);

    if (candidateJson.linkedin_post && candidateJson.facebook_post && candidateJson.instagram_post) {
      parsedOutput = candidateJson;
      usedModel = modelId;
      break;
    }
  } catch (err) {
    lastError = `${modelId}: ${err.message}`;
    continue;
  }
}

if (!parsedOutput) {
  throw new Error(`All OpenRouter models failed. Last error: ${lastError}`);
}

// Enforce strict PDF Section 2 & 3 business rule for text-only vs image posts
if (includeImage.toLowerCase() === 'no') {
  parsedOutput.image_gen_prompt = null;
  parsedOutput.image_description = null;
} else {
  if (!parsedOutput.image_gen_prompt) {
    parsedOutput.image_gen_prompt = `Photorealistic 4k editorial photography representing: ${topic}, modern lighting, high detail`;
  }
  if (!parsedOutput.image_description) {
    parsedOutput.image_description = `Visual illustration for ${topic}`;
  }
}

return [
  {
    json: {
      ...inputRow,
      ai_model_used: usedModel,
      linkedin_post: parsedOutput.linkedin_post,
      facebook_post: parsedOutput.facebook_post,
      instagram_post: parsedOutput.instagram_post,
      image_gen_prompt: parsedOutput.image_gen_prompt,
      image_description: parsedOutput.image_description,
      Image_URL: null
    }
  }
];

// ============================================================================
// CONDITIONAL VISUAL AI ENGINE (HUGGING FACE FLUX.1 + ZERO-COST IMGBB URL HOST)
// Triggered ONLY when 'Include Image?' == 'Yes'
// ============================================================================
const item = $input.first().json;
const prompt = item.image_gen_prompt || `Photorealistic 4k corporate photography of ${item.Topic}`;
const hfKey = $env.HUGGINGFACE_API_KEY;
const imgbbKey = $env.IMGBB_API_KEY;
const imgbbUrl = $env.IMGBB_UPLOAD_URL || '[https://api.imgbb.com/1/upload](https://api.imgbb.com/1/upload)';

if (!imgbbKey) {
  throw new Error('IMGBB_API_KEY is missing from environment variables.');
}

const hfEndpoints = [
  $env.HUGGINGFACE_MODEL_URL || '[https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-schnell](https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-schnell)',
  '[https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-dev](https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-dev)',
  '[https://router.huggingface.co/hf-inference/models/stabilityai/stable-diffusion-xl-base-1.0](https://router.huggingface.co/hf-inference/models/stabilityai/stable-diffusion-xl-base-1.0)'
];

let imageBuffer = null;

// 1. Attempt Hugging Face Serverless Inference endpoints
if (hfKey) {
  for (const endpoint of hfEndpoints) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: endpoint,
        headers: {
          'Authorization': `Bearer ${hfKey}`,
          'Content-Type': 'application/json',
          'Accept': 'image/jpeg'
        },
        body: JSON.stringify({ inputs: prompt }),
        encoding: 'arraybuffer',
        returnFullResponse: false,
        timeout: 45000
      });
      const buf = Buffer.from(resp);
      if (buf.length > 1000) {
        imageBuffer = buf;
        break;
      }
    } catch (err) {
      continue;
    }
  }
}

// 2. Fallback to Zero-Cost Public Image Router if HF free tier returns 410/402/503
if (!imageBuffer) {
  const encodedPrompt = encodeURIComponent(prompt.substring(0, 180));
  const fallbackUrls = [
    `[https://image.pollinations.ai/prompt/$](https://image.pollinations.ai/prompt/$){encodedPrompt}?width=1024&height=1024&nologo=true`,
    '[https://picsum.photos/1024/1024](https://picsum.photos/1024/1024)'
  ];
  for (const fbUrl of fallbackUrls) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: fbUrl,
        encoding: 'arraybuffer',
        timeout: 30000
      });
      const buf = Buffer.from(resp);
      if (buf.length > 1000) {
        imageBuffer = buf;
        break;
      }
    } catch (err) {
      continue;
    }
  }
}

if (!imageBuffer) {
  throw new Error('Failed to generate visual binary from Hugging Face and fallback image routers.');
}

// 3. Convert binary image to permanent public HTTPS URL via ImgBB
const base64Image = imageBuffer.toString('base64');
const formBody = `key=${encodeURIComponent(imgbbKey)}&image=${encodeURIComponent(base64Image)}&name=flux_${Date.now()}`;

const uploadResp = await this.helpers.httpRequest({
  method: 'POST',
  url: imgbbUrl,
  headers: {
    'Content-Type': 'application/x-www-form-urlencoded'
  },
  body: formBody,
  json: true,
  timeout: 45000
});

const publicUrl = uploadResp?.data?.url;
if (!publicUrl) {
  throw new Error('ImgBB did not return a valid public image URL.');
}

return [
  {
    json: {
      ...item,
      Image_URL: publicUrl
    }
  }
];

// Text-Only Branch ('Include Image?' == 'No')
// Bypasses Hugging Face completely and guarantees Image_URL is null
const item = $input.first().json;
return [
  {
    json: {
      ...item,
      image_gen_prompt: null,
      image_description: null,
      Image_URL: ''
    }
  }
];
